#include <stddef.h>

typedef float float_vec __attribute__((ext_vector_type(4)));

void vectorized_s244(int iterations, int LEN_1D, float* a, float* b, float* c, float* d) {
    int n = LEN_1D - 1;
    if (n <= 0) return;

    for (int nl = 0; nl < iterations; nl++) {
        // Handle first element (i=0) separately to break the recurrence
        if (n >= 1) {
            float b0 = b[0];
            float c0 = c[0];
            float d0 = d[0];
            float a1_old = a[1];
            a[0] = b0 + c0 * d0;
            b[0] = c0 + b0;
            a[1] = b[0] + a1_old * d0;
        }

        // Vectorize remaining elements starting from i=2
        int i = 2;
        for (; i <= n - 4; i += 4) {
            float_vec vb = *(float_vec*)(b + i);
            float_vec vc = *(float_vec*)(c + i);
            float_vec vd = *(float_vec*)(d + i);

            // a[i] = b[i] + c[i] * d[i]
            float_vec va = vb + vc * vd;
            *(float_vec*)(a + i) = va;

            // b[i] = c[i] + b[i]
            vb = vc + vb;
            *(float_vec*)(b + i) = vb;

            // a[i+1] = b[i] + a[i+1] * d[i]
            float_vec va_next = *(float_vec*)(a + i + 1);
            va_next = vb + va_next * vd;
            *(float_vec*)(a + i + 1) = va_next;
        }

        // Scalar cleanup: process remaining elements up to n-1
        for (; i < n; i++) {
            a[i] = b[i] + c[i] * d[i];
            b[i] = c[i] + b[i];
            a[i+1] = b[i] + a[i+1] * d[i];
        }
    }
}

void s244_opt(int iterations, int LEN_1D, float* a, float* b, float* c, float* d)
{
    for (int nl = 0; nl < iterations; nl++) {
        // First part: compute b[i] and the new a[i] (no loop-carried dependency)
        for (int i = 0; i < LEN_1D - 1; ++i) {
            b[i] = c[i] + b[i];
        }

        // Second part: compute a[i+1] using updated b[i] and original a[i+1]
        // No loop-carried dependency since a[i+1] uses only b[i] and a[i+1] (same iteration)
        for (int i = 0; i < LEN_1D - 1; ++i) {
            a[i+1] = b[i] + a[i+1] * d[i];
        }

        // Third part: compute a[i] using b[i] and c[i] * d[i]
        // Independent from previous loops
        for (int i = 0; i < LEN_1D - 1; ++i) {
            a[i] = b[i] + c[i] * d[i];
        }
    }
}
